mapper.select:
SELECT d.device_id, boundary_points.boundary_key, boundary_points.boundary_at, sample.collected_at, sample.energy_kwh FROM (
SELECT #{deviceId} AS device_id
) d CROSS JOIN (
SELECT #{boundary.boundaryKey} AS boundary_key, CAST(#{boundary.boundaryAt} AS DATETIME) AS boundary_at
) boundary_points LEFT JOIN device_measurement sample ON sample.id = COALESCE( ( SELECT before_sample.id FROM device_measurement before_sample WHERE before_sample.device_id = d.device_id AND before_sample.collected_at <= boundary_points.boundary_at AND before_sample.energy_kwh IS NOT NULL ORDER BY before_sample.collected_at DESC LIMIT 1 ), ( SELECT after_sample.id FROM device_measurement after_sample WHERE after_sample.device_id = d.device_id AND after_sample.collected_at >= boundary_points.boundary_at AND after_sample.energy_kwh IS NOT NULL ORDER BY after_sample.collected_at ASC LIMIT 1 ) ) ORDER BY d.device_id, boundary_points.boundary_at
